@@ -0,0 +1,12 @@
+import { createEventCard } from './event-card.js';
+
+export function sortChronologically(events) {
+  return events
+    .map((event, index) => ({ event, index, time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ event }) => event);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events).map(createEventCard);
+}

